#!/usr/bin/env python3
"""Writes lib/l10n/translations/<code>.dart from tool/l10n/<code>.json."""
import json, pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent


def dart_string(value: str) -> str:
    escaped = (value.replace('\\', '\\\\').replace("'", "\\'")
               .replace('$', '\\$').replace('\n', '\\n').replace('\r', ''))
    return f"'{escaped}'"


def generate(code: str):
    data = json.loads((ROOT / 'tool' / 'l10n' / f'{code}.json').read_text(encoding='utf-8'))
    lines = [
        '// GENERATED by tool/l10n_generate.py from tool/l10n/%s.json. Do not edit.' % code,
        '// Keys are the Indonesian source strings used with tr().',
        '// ignore_for_file: lines_longer_than_80_chars',
        '',
        'const Map<String, String> %s = {' % code,
    ]
    for key in sorted(data):
        lines.append(f'  {dart_string(key)}: {dart_string(data[key])},')
    lines.append('};')
    (ROOT / 'lib' / 'l10n' / 'translations' / f'{code}.dart').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(f'{code}: {len(data)} entries')


if __name__ == '__main__':
    for code in sys.argv[1:]:
        generate(code)
